from pathlib import Path
import re

INDEX=Path('index.html'); ADMIN=Path('admin.html')
# Homepage visual patch is already present; this runner keeps it idempotent.
s=INDEX.read_text(encoding='utf-8')
if 'MM-HOME-V10-CSS' not in s:
    s=s.replace('</head>',"<style id='MM-HOME-V10-CSS'>.home-v10{background:#f6f8fa}.mm-home-hero{position:relative;min-height:420px;background:#0d1e2b;overflow:hidden}.mm-home-hero .hero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.72}.mm-home-hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#0b1925,#0b192500)}.mm-hero-copy{position:relative;z-index:2;max-width:620px;padding:58px 0 70px;color:#fff}.mm-hero-copy h1{font-size:54px;line-height:1.02;font-weight:950}.mm-orange{display:inline-flex;background:#f58b00;color:#fff;border-radius:10px;padding:13px 19px;font-weight:900;text-decoration:none}.mm-cats{display:grid;grid-template-columns:repeat(12,1fr);gap:10px;padding:16px 0}.mm-cat{background:#fff;border:1px solid #e2e7eb;border-radius:12px;min-height:92px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-decoration:none;color:#18232d;font-weight:800}.mm-cat img{width:42px;height:42px;object-fit:contain}.mm-products{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.mm-product{background:#fff;border:1px solid #e0e5e9;border-radius:12px;overflow:hidden}.mm-product-img{height:175px;background:#f7f8f8}.mm-product-img img{width:100%;height:100%;object-fit:contain}.mm-product-body{padding:11px}.mm-product-btn{display:block;margin-top:7px;background:#f58b00;color:#fff;border-radius:8px;padding:9px;text-align:center;font-weight:900;text-decoration:none}.mm-rida{margin:10px 0 28px;border-radius:16px;overflow:hidden;background:#0b2030;color:#fff;position:relative}.mm-rida-bg{width:100%;height:235px;object-fit:cover;display:block;opacity:.78}.mm-rida-overlay{position:absolute;inset:0;padding:30px;background:linear-gradient(90deg,#071824ef,#07182422);display:flex;align-items:center}.mm-banners{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.mm-banner{min-height:155px;border-radius:14px;overflow:hidden;position:relative;background:#152536;color:#fff}.mm-banner img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}.mm-banner-copy{position:relative;z-index:2;padding:22px}.mm-brands{display:grid;grid-template-columns:repeat(8,1fr);gap:10px}.mm-brand{height:78px;background:#fff;border:1px solid #e1e6ea;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:950}.mm-brand img{max-width:78%;max-height:48px;object-fit:contain}@media(max-width:1000px){.mm-cats{grid-template-columns:repeat(6,1fr)}.mm-products{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.mm-cats{grid-template-columns:repeat(4,1fr)}.mm-products{grid-template-columns:repeat(2,1fr)}.mm-banners{grid-template-columns:1fr}.mm-brands{grid-template-columns:repeat(4,1fr)}}</style></head>",1)
    s=s.replace('<body class="home-v9">','<body class="home-v10">',1)
INDEX.write_text(s,encoding='utf-8')

s=ADMIN.read_text(encoding='utf-8')
if 'id="mmHomeMediaManager"' not in s:
    panel='''<div class="panel" id="mmHomeMediaManager" style="margin-top:16px"><div class="toolbar"><div><h3>🖼️ Imagens da página inicial</h3><p class="muted">Troca as imagens do Hero, banner RIDA, banners promocionais e marcas sem mexer no código.</p></div></div><div id="mmHomeMediaBody"></div><div style="margin-top:12px"><button class="btn primary" onclick="mmSaveHomeMedia()">Guardar imagens da homepage</button></div></div>'''
    s=s.replace('<div class="hero-editor">',panel+'<div class="hero-editor">',1)
    css='''<style id="MM-HOME-MEDIA-CSS">#mmHomeMediaBody{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mmhm-card{border:1px solid #e0e5e9;border-radius:12px;padding:12px}.mmhm-preview{height:110px;background:#f5f7f8;border-radius:9px;display:flex;align-items:center;justify-content:center;overflow:hidden;margin-bottom:8px}.mmhm-preview img{max-width:100%;max-height:100%;object-fit:contain}.mmhm-card input[type=file]{display:none}@media(max-width:700px){#mmHomeMediaBody{grid-template-columns:1fr}}</style>'''
    s=s.replace('</head>',css+'</head>',1)
    js='''<script id="MM-HOME-MEDIA-JS">(function(){const E=id=>document.getElementById(id);const X=v=>String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function U(file){let fd=new FormData();fd.append('file',file);let r=await fetch('/api/admin/upload',{method:'POST',body:fd,credentials:'same-origin'});let j=await r.json();if(!r.ok)throw Error(j.error||'Erro no upload');return j.url}async function load(){try{let d=await api('/api/admin/state'),hp=d.settings?.homepage||{},slides=d.settings?.hero_slides||[],logos=hp.brand_logos||{},b=hp.promo_banners||[];let h=`<div class="mmhm-card"><b>Hero principal</b><div class="mmhm-preview"><img src="${X(slides[0]?.image||'assets/RCH072D6-B24.png')}"></div><input id="mmhmHero" class="input" value="${X(slides[0]?.image||'')}"><label class="btn">Carregar imagem<input type="file" accept="image/*" onchange="mmPick(this,'mmhmHero')"></label></div><div class="mmhm-card"><b>Banner RIDA</b><div class="mmhm-preview"><img src="${X(hp.rida_banner?.image||'assets/RHD01075.png')}"></div><input id="mmhmRida" class="input" value="${X(hp.rida_banner?.image||'')}"><label class="btn">Carregar imagem<input type="file" accept="image/*" onchange="mmPick(this,'mmhmRida')"></label></div>`;for(let i=1;i<=3;i++){let p=b[i-1]||{};h+=`<div class="mmhm-card"><b>Banner ${i}</b><div class="mmhm-preview"><img src="${X(p.image||'assets/paint-placeholder.svg')}"></div><input id="mmhmP${i}" class="input" value="${X(p.image||'')}" placeholder="Imagem"><label class="btn">Carregar imagem<input type="file" accept="image/*" onchange="mmPick(this,'mmhmP${i}')"></label></div>`}for(let n of ['RIDA','NEUCE','SOUDAL','VITO','BOSCH','Makita','STANLEY','DEWALT'])h+=`<div class="mmhm-card"><b>Logo ${n}</b><div class="mmhm-preview" style="height:80px"><img src="${X(logos[n]||'')}"></div><input id="mmhmB${n}" class="input" value="${X(logos[n]||'')}" placeholder="Logo"><label class="btn">Carregar logo<input type="file" accept="image/*" onchange="mmPick(this,'mmhmB${n}')"></label></div>`;E('mmHomeMediaBody').innerHTML=h}catch(e){console.error(e)}}window.mmPick=async function(i,t){if(!i.files?.[0])return;try{E(t).value=await U(i.files[0]);}catch(e){alert(e.message)}};window.mmSaveHomeMedia=async function(){try{let d=await api('/api/admin/state'),hp=d.settings?.homepage||{},slides=d.settings?.hero_slides||[];if(slides[0])slides[0].image=E('mmhmHero').value;hp.rida_banner={image:E('mmhmRida').value};hp.promo_banners=[1,2,3].map(i=>({image:E('mmhmP'+i).value}));hp.brand_logos=hp.brand_logos||{};for(let n of ['RIDA','NEUCE','SOUDAL','VITO','BOSCH','Makita','STANLEY','DEWALT'])hp.brand_logos[n]=E('mmhmB'+n).value;await api('/api/admin/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hero_slides:slides,homepage:hp})});alert('Imagens da homepage guardadas.')}catch(e){alert(e.message)}};document.addEventListener('DOMContentLoaded',()=>setTimeout(load,350));})();</script>'''
    s=s.replace('</body>',js+'</body>',1)
s=s.replace('value="admin123"','value="admin"')
ADMIN.write_text(s,encoding='utf-8')
print('homepage_v10 done')
